-- This section of code, building on the icustays30 table generated by the icustays_data code, adds sepsis diagnosis, heart failure diagnosis, and central venous pressure monitoring information

-- Keep only the variables needed from icustays30
DROP TABLE IF EXISTS public.stay0;
CREATE TABLE public.stay0 AS
SELECT subject_id, hadm_id, stay_id, intime, outtime, los, survival_status, survival_day, thirty_day_death, one_year_death, hospital_expire_flag, 
    CASE 
        WHEN survival_status = 1 AND survival_day <= 30 THEN 1
        ELSE 0
    END AS surv30_status,
    LEAST(survival_day, 30) AS surv30_day,
    CASE 
        WHEN survival_status = 1 AND survival_day <= 365 THEN 1
        ELSE 0
    END AS surv365_status,
    LEAST(survival_day, 365) AS surv365_day,
gender, age, insurance, 
renal_disease, severe_liver_disease, metastatic_cancer, aids,
mbp_first AS mbp, heart_rate_first AS heart_rate, spo2_first AS spo2, 
pao2fio2ratio_first AS pao2fio2ratio, lactate_first AS lactate, creatinine_first AS creatinine, bun_first AS bun, potassium_first AS potassium, platelet_first AS platelet, inr_first AS inr, alt_first AS alt, bilirubin_total_first AS bilirubin, ntprobnp, 
sofa, apsiii,
vasoactive, mechanical_ventilation, lvef
FROM public.icustays30;

-- Find the icd_code and icd_version for heart failure and store them in the hf_icd table
DROP TABLE IF EXISTS public.hf_icd;
CREATE TABLE public.hf_icd AS
SELECT * FROM mimiciv_hosp.d_icd_diagnoses
WHERE LOWER(long_title) LIKE '%heart failure%'
    AND LOWER(long_title) NOT LIKE '%without heart failure%'
    AND LOWER(long_title) NOT LIKE '%postprocedural%';
    
-- Find hadm_ids of admissions that contain a heart failure diagnosis listed in the hf_icd table, from the diagnoses_icd table
DROP TABLE IF EXISTS public.hf_hadm;
CREATE TABLE public.hf_hadm AS
SELECT DISTINCT d.hadm_id
FROM mimiciv_hosp.diagnoses_icd AS d
INNER JOIN public.hf_icd AS h
ON d.icd_code = h.icd_code AND d.icd_version = h.icd_version;
-- Among the 546028 admissions, a total of 80858 hadm_ids had a heart failure diagnosis
SELECT COUNT(*) FROM mimiciv_hosp.admissions;
SELECT COUNT(*) FROM public.hf_hadm;

-- Add heart failure diagnosis status (binary)
DROP TABLE IF EXISTS public.stay1;
CREATE TABLE public.stay1 AS
SELECT ie.*,
    CASE 
        WHEN hf.hadm_id IS NOT NULL THEN 1
        ELSE 0
    END AS heart_failure
FROM public.stay0 AS ie
LEFT JOIN public.hf_hadm AS hf
ON ie.hadm_id = hf.hadm_id;
SELECT COUNT(*) FROM public.stay1; --74824
SELECT SUM(heart_failure) FROM public.stay1; --21616
-- Of the 74824 ICU records, a total of 21616 records had a heart failure diagnosis.

-- Add sepsis diagnosis status (binary) and the time of diagnosis
DROP TABLE IF EXISTS public.stay2;
CREATE TABLE public.stay2 AS
SELECT ie.*,
    CASE WHEN se.sepsis3 IS NOT NULL THEN 1 ELSE 0 END AS sepsis,
    sofa_time AS sepsis_time
FROM public.stay1 AS ie
LEFT JOIN mimiciv_derived.sepsis3 AS se
ON ie.stay_id = se.stay_id;
SELECT SUM(sepsis) FROM public.stay2; --37142

-- Add disease grouping
DROP TABLE IF EXISTS public.stay3;
CREATE TABLE public.stay3 AS
SELECT *,
    CASE 
        WHEN heart_failure=0 AND sepsis=1 THEN 'sepsis'
        WHEN heart_failure=1 AND sepsis=0 THEN 'HF'
        WHEN heart_failure=1 AND sepsis=1 THEN 'HFsepsis'
        ELSE NULL
    END AS disease_group
FROM public.stay2;
SELECT COUNT(disease_group) FROM public.stay3; --46627
SELECT COUNT(*) FROM public.stay3
WHERE disease_group='HFsepsis'; --12131

