-- Extract CVP monitoring information, including whether CVP monitoring was performed, the time of the first CVP measurement, and the value of the first CVP measurement.
-- Note that when determining the first CVP measurement, in addition to requiring that the CVP measurement time is the earliest among all CVP records for that stay_id, the CVP measurement time must also be after intime. After keeping only the first ICU stay_id under each admission hadm_id, I further explored the CVP records for each stay_id, including the measured value valuenum and measurement time charttime. I found that a small number of stay_ids (129 records) had their first CVP measurement earlier than intime, and all their charttimes were after intime-24h. For these 129 stay_ids, if the CVP records before intime are not considered and only those after intime are considered, then 123 stay_ids had CVP monitoring after intime, all of which were monitored within intime+12h, with 120 of them monitored within intime+6h. This indicates that, if CVP records before intime are ignored and only those after intime are considered, it barely affects the determination of whether this stay_id had early CVP monitoring. However, there are 129-123=6 stay_ids that had CVP records before intime but none after intime. If the start time for the first CVP measurement is extended to intime-6h, as the MIMIC official code repository does for many laboratory results, then only 7 stay_ids had their first CVP time between intime-24h and intime-6h, and all 7 records underwent early CVP monitoring (6 within 6h, 1 within 12h).
DROP TABLE IF EXISTS public.stay4;
CREATE TABLE public.stay4 AS
WITH cvp_filtered AS (
    -- Filter CVP measurement records from chartevents whose charttime falls between intime and outtime in icustays
    SELECT 
        ce.stay_id,
        ce.charttime AS cvp_time,
        ce.valuenum AS cvp,
        ie.intime
    FROM mimiciv_icu.chartevents AS ce
    LEFT JOIN mimiciv_icu.icustays AS ie 
        ON ce.stay_id = ie.stay_id
    WHERE ce.itemid = 220074
      AND ce.charttime BETWEEN ie.intime AND ie.outtime
),
cvp_ranked AS (
    -- Partition the above CVP monitoring records by stay_id, order by charttime, and mark the first record
    SELECT 
        stay_id,
        cvp_time,
        cvp,
        ROW_NUMBER() OVER (PARTITION BY stay_id ORDER BY cvp_time) AS cvp_order
    FROM cvp_filtered
)
-- Join back to stay3 to add the new fields
SELECT 
    ie.*,    
    EXTRACT(EPOCH FROM (cv.cvp_time - ie.intime))/3600 AS first_cvp_interval,
    cv.cvp AS first_cvp
FROM public.stay3 AS ie
LEFT JOIN cvp_ranked AS cv 
    ON ie.stay_id = cv.stay_id
    AND cv.cvp_order = 1;  -- Keep only the first record (the first after sorting)

SELECT COUNT(*) FROM public.stay4; --74824
SELECT COUNT(first_cvp) FROM public.stay4; --19731
